  'rs.the_visible_area_and_vector': 'The visible area and vector tiles need `lat`/`lng` (or a PostGIS geometry) and load again as the map moves. Vector tiles draw dots, lines and areas, without clustering or a list.',
  'rs.the_same_columns_as_the': 'The same columns as the map\'s own query. Empty the query to remove the layer.',
  'rs.the_condition_runs_on_the': 'The condition runs on the server: with PostGIS installed on a geometry/geography column, else on latitude and longitude.',
  'rs.users_switch_between_the_ticked': 'Users switch between the ticked views. Hours outside the range are added when an event needs them.',
  'rs.runs_as_the_application_s': 'Runs as the application\'s database role (row level security applies) with `:EVENT_ID` (the key column\'s value), `:NEW_START` and `:NEW_END` (same duration as before). Empty: events can\'t be dragged.',
  'rs.only_events_the_user_sees': 'Only events the user sees in this calendar can be moved; without a mouse, the edit link changes the dates.',
  'rs.not_while_the_pointer_or': 'Not while the pointer or the focus is in the carousel, nor for users who prefer reduced motion. A carousel has no "Show all".',
  'rs.a_chosen_region_gets_display': 'A chosen region gets `"display_selector": true` in its settings (a tab named after it), or the tab name: regions with the same tab name share one tab (e.g. smart filters and their report). Without JavaScript every region shows, with links to each.',
  'rs.gauge_charts_only_a_warning': 'Gauge charts only. A warning threshold above the critical one means low values are bad (e.g. warning 50, critical 20).',
  'rs.drill_down_column_takes_the': 'Drill-down: `#column#` takes the value from the point\'s row, `#series#` the name of its series. Columns only the link refers to are not drawn.',
  'rs.gantt_charts_with_a_task': 'Gantt charts with a `task_id` column. Runs as the application\'s database role (row level security applies) with `:TASK_ID`, `:NEW_START` and `:NEW_END` (`YYYY-MM-DD`, or `YYYY-MM-DDTHH:MM` by the hour; a milestone gets the same start and end). Empty: tasks can\'t be dragged.',
  'rs.only_tasks_the_user_sees': 'Only tasks the user sees in this chart can be moved; the chart is drawn again from its query afterwards.',
