  'rm.chk.no_privilege': 'No privilege roles: any valid token of the application (handlers may add roles)',
  'rm.response_as': '{request} as {as}',
  'rm.try_intro': 'Sends the request to the real endpoint: a PUT, POST or DELETE changes data. {as} an account issues a short-lived token for it, as App › REST API does; without one you see what a caller without a token gets.',
  'rm.intro': 'RESTful Services modules: a module is a base path of an application, its templates are URIs with `:parameters`, and each template has handlers per method with their source: a collection query, a single row, SQL, a PL/pgSQL block or a media resource. Handlers run as the application\'s database role with the caller as `meta.app_user()`, so its grants and row level security apply; parameters are bound, never pasted into the SQL. Every module has an OpenAPI document. Modules belong to their application: they travel with its export (also in Shared Components › RESTful Services).',
  'rm.source_help': 'Binds, upper case: path parameters ({params}), query parameters and JSON body fields; `:BODY` is the whole body; `:APP_USER` is the caller. Values are bound, never pasted into the SQL. PL/pgSQL: a block (`declare … begin … end`, or statements) that answers with `perform meta.rest_reply(jsonb_build_object(…), 201)`. Media: a query returning `content_type`, `content` and optionally `filename`.',
  'rm.params_help': 'One per line: `name query|body [{types}] [required] [description]`. They go into the OpenAPI document and the Try it form; a required one missing answers 400.',
  'rm.e.params_line': 'Parameters, line {n}: write "name query" or "name body", then optionally a type ({types}), "required" and a description.',
  'rm.e.choose_app': 'Choose an application of this workspace.',
