  'wres.servers_intro': 'Named base URLs of {workspace}: a REST data source, a REST source catalog or an AI service names a server and a path instead of a full URL, so moving from development to production changes one value here (or one environment variable), and every source on the server follows at once. The URL still passes every check a full URL does: the installation\'s allow-list, this workspace\'s {network} list and the address checks when the call is made.',
