  'wres.files_intro': 'CSS, JavaScript, JSON, images and fonts that every application of {workspace} may use: an application loads one on every page with {tag} in Shared Components → Static application files → Every page loads (a page: Page → Appearance), and templates, HTML and links use {sub} for their URL. Each application serves them from its own address ({path}), never another workspace\'s. Up to {size} per file; no HTML. They travel with the workspace export.',
  'wres.type_help': 'basic: user name + password · header: an HTTP header with the secret (API key) · bearer: Authorization: Bearer <secret> · oauth2: client credentials, password or refresh token grant · aws_sigv4: an S3-compatible object store.',
  'wres.credentials_intro': 'Web credentials of {workspace} that its applications use by name in REST data sources, the Invoke API process, remote servers and object storage, so a key is entered once for the workspace. An application\'s own credential (Shared Components → Web credentials) with the same name wins. Secrets are encrypted with the server\'s key, never shown again and never exported.',
